[HttpGet("orders/{orderId}")]
[Authorize]
public async Task<IActionResult> GetOrder(
    Guid orderId,
    IAuthorizationService authz)
{
    var order = await _db.Orders.AsNoTracking()
        .FirstOrDefaultAsync(o => o.Id == orderId);
    if (order is null) return NotFound();

    var result = await authz.AuthorizeAsync(User, order, "OrderOwner");
    if (!result.Succeeded) return Forbid(); // 403 — do not leak existence via 404 debate

    return Ok(_mapper.ToDto(order));
}

builder.Services.AddRateLimiter(options =>
{
    options.RejectionStatusCode = StatusCodes.Status429TooManyRequests;
    options.GlobalLimiter = PartitionedRateLimiter.Create<HttpContext, string>(ctx =>
        RateLimitPartition.GetFixedWindowLimiter(
            ctx.User.Identity?.Name ?? ctx.Connection.RemoteIpAddress?.ToString() ?? "anon",
            _ => new FixedWindowRateLimiterOptions
            {
                PermitLimit = 100,
                Window = TimeSpan.FromMinutes(1)
            }));
});

builder.WebHost.ConfigureKestrel(o =>
{
    o.Limits.MaxRequestBodySize = 1_048_576; // 1 MB
});

app.UseRateLimiter();

if (!app.Environment.IsDevelopment())
{
    app.UseExceptionHandler();
    app.UseHsts();
}
app.UseHttpsRedirection();

app.Use(async (ctx, next) =>
{
    ctx.Response.Headers["X-Content-Type-Options"] = "nosniff";
    ctx.Response.Headers["Cache-Control"] = "no-store";
    await next();
});

// Restrict CORS — never AllowAnyOrigin with credentials
builder.Services.AddCors(o => o.AddPolicy("Spa", p => p
    .WithOrigins("https://app.example.com")
    .AllowAnyHeader()
    .AllowAnyMethod()));

public class SecurityAuditMiddleware(RequestDelegate next, ILogger<SecurityAuditMiddleware> log)
{
    public async Task InvokeAsync(HttpContext ctx)
    {
        await next(ctx);
        if (ctx.Response.StatusCode is 401 or 403 or 429)
        {
            log.LogWarning(
                "SecurityEvent {Status} {Method} {Path} User={User} ClientId={Client}",
                ctx.Response.StatusCode,
                ctx.Request.Method,
                ctx.Request.Path,
                ctx.User.FindFirstValue("sub") ?? "anonymous",
                ctx.User.FindFirstValue("client_id"));
        }
    }
}
